detail.parent:
{
  baseMaxima: BASE_MAXIMA_COTIZACION_LEGACY[anio],
  tiposSeguridadSocial: TIPOS_SEGURIDAD_SOCIAL_LEGACY,
  mei: obtenerTiposMei(anio),
  solidaridad: obtenerPoliticaSolidaridad(anio),
}

detail.text:
actividad.etapas.map((e, instancia) =>
        crearLineaCalculo({
          siteId: "anual.explicito.actividad.etapa",
          instancia: instancia,
          importe: new D(e.importe),
          unidad: "EUR",
          etiqueta: `${e.reglaId}: ${e.id}`,
          formula: e.formula,
        })
      )

EffectArray.reduce(
    EffectArray.map(ganancias, (ganancia) =>
      calcularGananciaPatrimonialPorTransmision({
        anio,
        edadContribuyente,
        ganancia,
        convertirCentimos,
      })
    ),
    {
      gananciaTotal: IMPORTE_CERO,
      gananciaExenta: IMPORTE_CERO,
      gananciaSujetaAhorro: IMPORTE_CERO,
      gananciaSujetaGeneral: IMPORTE_CERO,
    },
    (total, ganancia) => ({
      gananciaTotal: total.gananciaTotal.plus(ganancia.gananciaTotal),
      gananciaExenta: total.gananciaExenta.plus(ganancia.gananciaExenta),
      gananciaSujetaAhorro: total.gananciaSujetaAhorro.plus(
        ganancia.baseIntegracion === "base-ahorro"
          ? ganancia.gananciaSujeta
          : IMPORTE_CERO
      ),
      gananciaSujetaGeneral: total.gananciaSujetaGeneral.plus(
        ganancia.baseIntegracion === "base-general"
          ? ganancia.gananciaSujeta
          : IMPORTE_CERO
      ),
    })
  )

caso.rendimientos.map((r) => ({
      id: r.id,
      clase: r.clase,
      integro: r.integro,
    }))

